const icons={menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',layout:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',megaphone:'<path d="m3 11 18-5v12L3 14v-3Z"/><path d="M11.6 16 13 21H8l-1.2-6"/>',messages:'<path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4v8Z"/>',clipboard:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 9h6M9 13h6M9 17h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/>',alert:'<path d="M10.3 3.6 2.2 18a2 2 0 0 0 1.7 3h16.2a2 2 0 0 0 1.7-3L13.7 3.6a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4M12 17h.01"/>',arrow:'<path d="M5 12h14M15 8l4 4-4 4"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',send:'<path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/>',external:'<path d="M15 3h6v6M10 14 21 3M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',chevleft:'<path d="m15 18-6-6 6-6"/>',chevright:'<path d="m9 18 6-6-6-6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6"/>'};
document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[el.dataset.icon]}</svg>`});
const assignments=[
 {id:1,subject:'OOP',title:'Lab 4: Inheritance',description:'เขียนโปรแกรมเรื่องการสืบทอด และส่ง Source Code ตามข้อกำหนด',section:'SEC 1',due:'19 ก.ย. 2569 · 23:59',day:19,submission:'Microsoft Teams',status:'DOING',urgency:'24',resource:'เอกสาร Lab 4',note:''},
 {id:2,subject:'DATABASE',title:'ออกแบบ ER Diagram',description:'วิเคราะห์ Requirement และแปลงเป็น ER Model พร้อมระบุ Cardinality',section:'ALL',due:'20 ก.ย. 2569 · 18:00',day:20,submission:'Google Classroom',status:'TODO',urgency:'48',resource:'โจทย์งานและตัวอย่าง',note:''},
 {id:3,subject:'SOFTWARE ENGINEERING',title:'Software Requirement Specification',description:'จัดทำเอกสาร SRS ของระบบตามหัวข้อและรูปแบบที่กำหนด',section:'SEC 2',due:'25 ก.ย. 2569 · 23:59',day:25,submission:'Microsoft Teams',status:'TODO',urgency:null,resource:'SRS Template',note:''},
 {id:4,subject:'WEB DEVELOPMENT',title:'Responsive Dashboard',description:'พัฒนาหน้า Dashboard ด้วย React และ Tailwind CSS ให้รองรับทุกหน้าจอ',section:'SEC 1',due:'28 ก.ย. 2569 · 20:00',day:28,submission:'GitHub Classroom',status:'DONE',urgency:null,resource:'Starter repository',note:'ตรวจ responsive บนมือถือแล้ว'}
];
const state={section:'ALL',status:'ALL',subject:'ALL',sort:'near',view:'list',urgentOnly:false,selected:null};
const els={list:document.querySelector('#listView'),calendar:document.querySelector('#calendarView'),count:document.querySelector('#resultCount'),status:document.querySelector('#statusFilter'),subject:document.querySelector('#subjectFilter'),sort:document.querySelector('#sortFilter'),backdrop:document.querySelector('#modalBackdrop'),drawerBody:document.querySelector('#drawerBody'),drawerTitle:document.querySelector('#drawerTitle'),drawerSubject:document.querySelector('#drawerSubject'),toast:document.querySelector('#toast')};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]}</svg>`;
const statusColor=s=>s==='DOING'?'#c2410c':s==='DONE'?'#15803d':'#475569';
function filtered(){let data=assignments.filter(a=>(state.section==='ALL'||a.section==='ALL'||a.section===state.section)&&(state.status==='ALL'||a.status===state.status)&&(state.subject==='ALL'||a.subject===state.subject)&&(!state.urgentOnly||a.urgency));return data.sort((a,b)=>state.sort==='far'?b.day-a.day:state.sort==='updated'?b.id-a.id:a.day-b.day)}
function urgencyBadge(a){return a.urgency==='24'?'<span class="badge urgent">ด่วน · ภายใน 24 ชม.</span>':a.urgency==='48'?'<span class="badge warning">ภายใน 48 ชม.</span>':''}
function card(a){return `<article class="assignment-card" style="--status-color:${statusColor(a.status)}"><div><div class="subject-row"><span class="subject">${a.subject}</span><span class="badge">${a.section}</span>${urgencyBadge(a)}</div><h3>${a.title}</h3><p class="description">${a.description}</p></div><div class="meta-stack"><div class="meta">${icon('clock')}<div><span>กำหนดส่ง</span><br><strong>${a.due}</strong></div></div><div class="meta">${icon('send')}<div><span>ส่งทาง</span><br><strong>${a.submission}</strong></div></div></div><div class="card-actions"><div class="status-control" aria-label="สถานะ ${a.title}">${['TODO','DOING','DONE'].map(s=>`<button class="${a.status===s?'active':''}" data-status="${s}" data-id="${a.id}">${s}</button>`).join('')}</div><div class="action-row"><a class="link-button" href="#" data-resource="${a.id}">${icon('external')}เอกสาร</a><button class="secondary-button" data-detail="${a.id}">ดูรายละเอียด ${icon('arrow')}</button></div></div></article>`}
function renderList(){const data=filtered();els.count.textContent=data.length;els.list.innerHTML=data.length?data.map(card).join(''):`<div class="empty-state"><div class="empty-icon">${icon('search')}</div><h3>ไม่พบงานที่ตรงกับตัวกรอง</h3><p>ลองเปลี่ยน Section สถานะ หรือรายวิชา</p><button class="secondary-button" id="clearFilters">ล้างตัวกรอง</button></div>`;document.querySelector('#sidebarCount').textContent=assignments.filter(a=>a.status!=='DONE').length}
function renderCalendar(){const byDay=Object.groupBy?Object.groupBy(filtered(),a=>a.day):filtered().reduce((g,a)=>((g[a.day]??=[]).push(a),g),{});let cells='';for(let i=30;i<=30;i++)cells+=`<div class="day muted"><span class="day-number">${i}</span></div>`;for(let day=1;day<=30;day++){cells+=`<div class="day"><span class="day-number">${day}</span>${(byDay[day]||[]).map(a=>`<button class="calendar-task ${a.status} ${a.urgency?'urgent-task':''}" data-detail="${a.id}">${a.subject} · ${a.title}</button>`).join('')}</div>`}for(let i=1;i<=4;i++)cells+=`<div class="day muted"><span class="day-number">${i}</span></div>`;els.calendar.innerHTML=`<div class="calendar-head"><div><p class="eyebrow">CALENDAR VIEW</p><h3>กันยายน 2569</h3></div><div class="calendar-nav"><button class="icon-button" aria-label="เดือนก่อนหน้า">${icon('chevleft')}</button><button class="icon-button" aria-label="เดือนถัดไป">${icon('chevright')}</button></div></div><div class="calendar-grid">${['จันทร์','อังคาร','พุธ','พฤหัส','ศุกร์','เสาร์','อาทิตย์'].map(d=>`<div class="weekday">${d}</div>`).join('')}${cells}</div><div class="legend"><span style="color:#475569"><i></i>TODO</span><span style="color:#c2410c"><i></i>DOING</span><span style="color:#15803d"><i></i>DONE</span><span style="color:#b91c1c"><i></i>งานด่วน</span></div>`;els.count.textContent=filtered().length}
function render(){renderList();renderCalendar();document.querySelector('#urgentCount').textContent=`${assignments.filter(a=>a.urgency&&a.status!=='DONE').length} งาน`;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));els.list.classList.toggle('hidden',state.view!=='list');els.calendar.classList.toggle('hidden',state.view!=='calendar')}
function openDetail(id){const a=assignments.find(x=>x.id===Number(id));state.selected=a;els.drawerSubject.textContent=a.subject;els.drawerTitle.textContent=a.title;els.drawerBody.innerHTML=`<div class="detail-section"><h3>รายละเอียดงาน</h3><p>${a.description}</p></div><div class="detail-section detail-grid"><div class="detail-item"><span>Section</span><strong>${a.section}</strong></div><div class="detail-item"><span>สถานะปัจจุบัน</span><strong style="color:${statusColor(a.status)}">${a.status}</strong></div><div class="detail-item"><span>กำหนดส่ง</span><strong>${a.due}</strong></div><div class="detail-item"><span>ช่องทางส่ง</span><strong>${a.submission}</strong></div></div><div class="detail-section"><h3>เอกสารและลิงก์</h3><a class="link-button" href="#">${icon('file')}${a.resource}</a></div><div class="detail-section"><h3>อัปเดตสถานะส่วนตัว</h3><div class="status-control" style="--status-color:${statusColor(a.status)}">${['TODO','DOING','DONE'].map(s=>`<button class="${a.status===s?'active':''}" data-drawer-status="${s}">${s}</button>`).join('')}</div></div><div class="detail-section"><label for="personalNote"><h3>บันทึกส่วนตัว</h3></label><textarea id="personalNote" placeholder="จดสิ่งที่ต้องทำเพิ่มเติม...">${a.note}</textarea></div><div class="drawer-footer"><button class="secondary-button" id="cancelDrawer">ยกเลิก</button><button class="primary-button" id="saveDetail">บันทึกการเปลี่ยนแปลง</button></div>`;els.backdrop.classList.remove('hidden');document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('#closeDrawer').focus(),0)}
function closeDetail(){els.backdrop.classList.add('hidden');document.body.style.overflow='';state.selected=null}
function toast(msg){els.toast.textContent=msg;els.toast.classList.add('show');setTimeout(()=>els.toast.classList.remove('show'),2200)}
document.addEventListener('click',e=>{const status=e.target.closest('[data-status]');if(status){assignments.find(a=>a.id===Number(status.dataset.id)).status=status.dataset.status;render();toast('อัปเดตสถานะแล้ว');return}const detail=e.target.closest('[data-detail]');if(detail){openDetail(detail.dataset.detail);return}const resource=e.target.closest('[data-resource]');if(resource){e.preventDefault();toast('ลิงก์ตัวอย่าง — พร้อมเชื่อมต่อเอกสารจริง');return}const section=e.target.closest('#sectionFilter button');if(section){state.section=section.dataset.value;state.urgentOnly=false;document.querySelectorAll('#sectionFilter button').forEach(b=>b.classList.toggle('active',b===section));render();return}const view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;render();return}if(e.target.closest('#showUrgent')){state.urgentOnly=!state.urgentOnly;render();document.querySelector('#showUrgent').firstChild.textContent=state.urgentOnly?'แสดงงานทั้งหมด ':'ดูงานด่วนทั้งหมด ';return}if(e.target.closest('#closeDrawer')||e.target.closest('#cancelDrawer')||e.target===els.backdrop)closeDetail();if(e.target.closest('#saveDetail')){state.selected.note=document.querySelector('#personalNote').value;closeDetail();render();toast('บันทึกรายละเอียดแล้ว')}const drawerStatus=e.target.closest('[data-drawer-status]');if(drawerStatus){state.selected.status=drawerStatus.dataset.drawerStatus;openDetail(state.selected.id)}if(e.target.closest('#clearFilters'))resetFilters();if(e.target.closest('#menuButton')){document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#scrim').classList.toggle('open')}if(e.target.closest('#scrim')){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#scrim').classList.remove('open')}});
function resetFilters(){state.section=state.status=state.subject='ALL';state.urgentOnly=false;els.status.value=els.subject.value='ALL';document.querySelectorAll('#sectionFilter button').forEach(b=>b.classList.toggle('active',b.dataset.value==='ALL'));render()}
els.status.addEventListener('change',e=>{state.status=e.target.value;render()});els.subject.addEventListener('change',e=>{state.subject=e.target.value;render()});els.sort.addEventListener('change',e=>{state.sort=e.target.value;render()});document.querySelector('#closeDrawer').addEventListener('click',closeDetail);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!els.backdrop.classList.contains('hidden'))closeDetail()});[...new Set(assignments.map(a=>a.subject))].forEach(s=>els.subject.add(new Option(s,s)));render();
